, correspondencias as (
  select distinct c.id as composicao_id, cc.id as componente_id, custos.custo_unitario
  from custos
  join public.composicoes c on c.codigo = custos.codigo_composicao
  join public.composicao_componentes cc on cc.composicao_id = c.id
    and cc.codigo is not distinct from custos.codigo_componente
    and cc.nome = custos.nome
    and cc.unidade = custos.unidade
    and cc.quantidade = custos.quantidade
  where c.codigo like 'UFCA:%'
    and cc.custo_unitario = 0
), atualizados as (
  update public.composicao_componentes cc
  set custo_unitario = correspondencias.custo_unitario
  from correspondencias
  where cc.id = correspondencias.componente_id
  returning cc.composicao_id
)
update public.composicoes c
set custo_unitario = totais.total
from (
  select c2.id, round(sum(cc.quantidade * cc.custo_unitario), 4) as total
  from public.composicoes c2
  join public.composicao_componentes cc on cc.composicao_id = c2.id
  where c2.id in (select composicao_id from atualizados)
  group by c2.id
) totais
where c.id = totais.id;
